#!/usr/bin/env python3
# ─────────────────────────────────────────────────────────────────────────────
# base.py — SlamEvaluator: the shared skeleton every per-SLAM evaluator extends.
#
# WHY THIS EXISTS
#   Evaluating one HIL SLAM run means: read the recorded bag, align the SLAM
#   trajectory to ground truth, compute ATE (APE RMSE), read the timing/CPU
#   sidecar CSVs, and draw the same plots the offline EuRoC study drew
#   (SLAM_benchmark/images/, generated by src/orbslam2/tools/generate_paper_images.py).
#
#   Almost all of that is identical across SLAM backends. The ONLY things that
#   differ per backend are small and declarative — which timing file to read,
#   what colour/label to draw, how to name threads. So this base class does the
#   heavy lifting once, and each backend (orbslam2.py, ov2slam.py) is a tiny
#   subclass that fills in those few blanks.
#
# ADDING A NEW SLAM BACKEND (you barely need to know ROS):
#   1. Make a new file, e.g. rtabmap.py.
#   2. Subclass SlamEvaluator and set the class attributes marked "OVERRIDE" below
#      (label, colour, which timing CSV your node writes, its category name).
#   3. If your node names its threads oddly, override thread_role_order().
#   4. Register it in __main__.py's SLAM_REGISTRY.
#   That's it — the bag reading, evo alignment, ATE, and every plot come for free.
#
# ATE'S HEADLINE NUMBERS (rmse/mean/median/min/max/std -- what gets reported,
#   plotted, and compared) come from literally shelling out to the real
#   `evo_ape` CLI (github.com/MichaelGrupp/evo, the same tool the offline
#   ORB-SLAM2 / OV2SLAM benchmarks used), parsing its stdout -- NOT evo's Python
#   API with our own parameters. This matters: an earlier version of this file
#   called evo.core's association/align/APE functions directly with a
#   hand-picked --t_max_diff=0.05, and the result was substantially different
#   from evo_ape's own default (--t_max_diff=0.01, see evo/cli/ape_parser.py) --
#   nearly 2x on some runs. Shelling out to the actual CLI guarantees the
#   reported numbers are exactly what running `evo_ape` by hand would show, and
#   can never silently drift from evo's own defaults again.
#   evo's Python API (evo.core) is still used for ONE thing the CLI's stdout
#   doesn't expose: the per-point aligned positions needed to draw the
#   trajectory plot, and the scale factor for the coverage metric. That
#   alignment call uses the same 0.01 default for consistency with the CLI
#   numbers it's drawn alongside.
#   Run this with the evo venv's python: benchmarks/.evo_venv/bin/python -m slam_eval <run_dir>
# ─────────────────────────────────────────────────────────────────────────────
from __future__ import annotations

import copy
import csv
import subprocess
import sys
from pathlib import Path

import numpy as np
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

from rosbags.highlevel import AnyReader

from evo.core import metrics, sync
from evo.core.trajectory import PoseTrajectory3D

_EVO_T_MAX_DIFF = 0.01   # matches evo_ape CLI's own default (ape_parser.py)


# Reference lines drawn on the plots, matching generate_paper_images.py exactly.
_RMSE_LINES = [(0.05, "5 cm"), (0.10, "10 cm")]          # grey dashed
_FE_BUDGET_MS = 50.0                                      # "20 Hz budget", firebrick
_CPU_CORE_LINES = [(100.0, "1 core"), (200.0, "2 cores")]  # grey dashed
_THREAD_COLOR = "#7a5195"


class SlamEvaluator:
    # ── OVERRIDE THESE IN YOUR SUBCLASS ──────────────────────────────────────
    slam_type: str = "base"          # must match meta.txt's slam_type=
    label: str = "SLAM"              # legend / title text, e.g. "ORB-SLAM2"
    color: str = "#6a4c93"           # bar/line colour (paper palette)
    frontend_csv: str = ""           # per-frame timing CSV filename in the run dir
    frontend_category: str = "frontend/full_tracking"  # category column value to keep
    # ─────────────────────────────────────────────────────────────────────────

    def __init__(self, rundir: Path):
        self.rundir = Path(rundir)
        self.metrics: dict = {}

    # ── meta.txt helpers ─────────────────────────────────────────────────────
    def meta_val(self, key: str) -> str:
        f = self.rundir / "meta.txt"
        if not f.exists():
            return ""
        for line in f.read_text().splitlines():
            if line.startswith(key + "="):
                return line.split("=", 1)[1].strip()
        return ""

    # ── bag reading (shared — no backend cares how the bag is stored) ─────────
    def _find_bag(self) -> Path:
        if (self.rundir / "metadata.yaml").exists():
            return self.rundir
        cands = list(self.rundir.glob("**/metadata.yaml"))
        if cands:
            return cands[0].parent
        return self.rundir

    def read_bag(self):
        """Extract SLAM pose, GT pose, and /bench/state markers from the bag.
        Returns (slam Nx4 [t,x,y,z], gt Mx4 [t,x,y,z], bench [(t,str)])."""
        slam, gt, bench = [], [], []
        topics = {"/slam/pose", "/sim/drone_pose", "/bench/state"}
        with AnyReader([self._find_bag()]) as reader:
            conns = [c for c in reader.connections if c.topic in topics]
            if not conns:
                sys.exit("bag has neither /slam/pose nor /sim/drone_pose — wrong bag?")
            for conn, ts, raw in reader.messages(connections=conns):
                t = ts * 1e-9
                m = reader.deserialize(raw, conn.msgtype)
                if conn.topic == "/slam/pose":
                    p = m.pose.position
                    slam.append((t, p.x, p.y, p.z))
                elif conn.topic == "/sim/drone_pose":
                    if len(m.data) >= 3:
                        x, y, z = m.data[0], m.data[1], m.data[2]
                        # Simulink publishes zero-initialised placeholder samples
                        # before the model runs; no real telemetry is exactly 0,0,0.
                        if x == 0.0 and y == 0.0 and z == 0.0:
                            continue
                        gt.append((t, x, y, z))
                elif conn.topic == "/bench/state":
                    bench.append((t, m.data))
        return np.array(slam), np.array(gt), bench

    @staticmethod
    def _find_fsm_start(bench):
        """First FSM /bench/state message (comma-delimited "STATE,t,ctrl,dist").
        The init_gate publishes bare strings (SLAM_READY, no comma) before the
        FSM launches, so a comma marks the real mission start. None if no FSM."""
        for t, s in bench:
            if "," in s:
                return t
        return None

    # ── TUM export (evo reads these; also handy artifacts) ───────────────────
    @staticmethod
    def _write_tum(path: Path, t: np.ndarray, xyz: np.ndarray):
        # TUM: timestamp tx ty tz qx qy qz qw  (identity quaternion — position only)
        with open(path, "w") as f:
            for ti, (x, y, z) in zip(t, xyz):
                f.write(f"{ti:.9f} {x:.6f} {y:.6f} {z:.6f} 0 0 0 1\n")

    @staticmethod
    def _to_evo(t: np.ndarray, xyz: np.ndarray) -> PoseTrajectory3D:
        quat = np.tile([1.0, 0.0, 0.0, 0.0], (len(t), 1))  # wxyz identity
        return PoseTrajectory3D(positions_xyz=xyz, orientations_quat_wxyz=quat, timestamps=t)

    # ── ATE: real evo_ape CLI for the headline stats, evo API for plot geometry
    def _evo_ape_cli(self, gt_tum: Path, slam_tum: Path) -> dict | None:
        """Run the literal `evo_ape` command and parse its stdout. This is the
        source of truth for rmse/mean/median/min/max/std -- see the module
        docstring for why. Returns None if evo_ape reports too few associated
        pairs / fails outright (e.g. a window with almost no overlap)."""
        proc = subprocess.run(
            ["evo_ape", "tum", str(gt_tum), str(slam_tum), "--align", "--correct_scale"],
            capture_output=True, text=True,
        )
        if proc.returncode != 0:
            print(f"  evo_ape failed on {slam_tum.name}: {proc.stderr.strip()[-300:]}")
            return None
        out = {}
        for line in proc.stdout.splitlines():
            parts = line.split()
            if len(parts) == 2 and parts[0] in ("max", "mean", "median", "min", "rmse", "sse", "std"):
                out[parts[0]] = float(parts[1])
        if "rmse" not in out:
            print(f"  evo_ape produced no parseable stats for {slam_tum.name}")
            return None
        return out

    def _align_for_plot(self, slam, gt):
        """evo API alignment (max_diff matching evo_ape's own default) -- used
        ONLY for the trajectory plot's point positions and the scale factor fed
        into the coverage metric. Not the source of any reported ATE statistic;
        see _evo_ape_cli() for those."""
        gt_traj = self._to_evo(gt[:, 0], gt[:, 1:4])
        slam_traj = self._to_evo(slam[:, 0], slam[:, 1:4])
        ref, est = sync.associate_trajectories(gt_traj, slam_traj, max_diff=_EVO_T_MAX_DIFF)
        if ref.num_poses < 10:
            sys.exit(f"only {ref.num_poses} associated poses — did SLAM and GT overlap?")
        est_aligned = copy.deepcopy(est)
        _, _, scale = est_aligned.align(ref, correct_scale=True)   # Sim3 (monocular)
        return ref, est_aligned, float(scale)

    def compute_ate(self, slam, gt):
        """Whole-bag ATE -- includes whatever happened before the FSM started
        (e.g. the init_gate's own warm-up wiggle). See compute_ate_mission()
        for the number that actually reflects tracking quality during the
        real mission, which is the one to report/compare."""
        ref, est_aligned, scale = self._align_for_plot(slam, gt)
        ate = self._evo_ape_cli(self.rundir / "gt_traj.tum", self.rundir / "slam_traj.tum")
        return ate, ref, est_aligned, scale

    def compute_ate_mission(self, slam, gt, bench):
        """ATE restricted to t >= FSM start (excludes the init_gate's pre-mission
        warm-up). This is the number that should be reported/compared -- the
        pre-mission window is typically small (~20 samples here) but its error is
        disproportionately larger (SLAM just initialized, scale/pose not yet
        settled), and RMSE squares errors, so a handful of those points can
        noticeably inflate the whole-bag number relative to what the settled,
        in-mission tracking actually looks like. Returns None if no FSM marker
        (e.g. a non-gated run) or too few post-FSM samples."""
        fsm_t = self._find_fsm_start(bench)
        if fsm_t is None:
            return None
        gt_m = gt[gt[:, 0] >= fsm_t]
        slam_m = slam[slam[:, 0] >= fsm_t]
        if len(gt_m) < 10 or len(slam_m) < 10:
            return None
        gt_tum = self.rundir / "gt_mission.tum"
        slam_tum = self.rundir / "slam_mission.tum"
        self._write_tum(gt_tum, gt_m[:, 0], gt_m[:, 1:4])
        self._write_tum(slam_tum, slam_m[:, 0], slam_m[:, 1:4])
        ate = self._evo_ape_cli(gt_tum, slam_tum)
        return (ate,) if ate is not None else None

    # ── per-frame front-end timing (subclass supplies the filename) ───────────
    def read_frontend_timing(self):
        """Return (x, durations_ms) for self.frontend_category, ordered by wall
        clock (the 'wall_ts' column). x is a simple 0..N-1 sample index, NOT the
        frame_id: OV2SLAM restarts frame_id at 0 on a SLAM reset, so frame_id is
        not monotonic across a run — wall_ts always is. Only the mean/std (which
        are order-independent) feed the headline bar; x just orders the timeseries
        plot. Works for any CSV with 'wall_ts','category','duration_ms' columns
        (both ORB-SLAM2's timing_events.csv and OV2SLAM's ov2slam_timing_events.csv)."""
        if not self.frontend_csv:
            return np.array([]), np.array([])
        f = self.rundir / self.frontend_csv
        if not f.exists():
            return np.array([]), np.array([])
        ts, durs = [], []
        with open(f, newline="") as fh:
            for row in csv.DictReader(fh):
                if row.get("category", "") != self.frontend_category:
                    continue
                try:
                    ts.append(float(row["wall_ts"]))
                    durs.append(float(row["duration_ms"]))
                except (KeyError, ValueError):
                    continue
        if not durs:
            return np.array([]), np.array([])
        durs = np.array(durs)[np.argsort(ts)]
        return np.arange(len(durs)), durs

    # ── CPU / thread CPU (shared sampler format, backend-agnostic) ────────────
    def read_cpu(self):
        f = self.rundir / "slam_process_cpu.csv"
        if not f.exists():
            return {}
        cpu, mem, thr = [], [], []
        with open(f, newline="") as fh:
            for row in csv.DictReader(fh):
                try:
                    cpu.append(float(row["cpu_percent"]))
                    mem.append(float(row["mem_mb"]))
                    thr.append(int(float(row["threads"])))
                except (KeyError, ValueError):
                    continue
        if not cpu:
            return {}
        a = np.array(cpu)
        return {"cpu_mean": float(a.mean()), "cpu_std": float(a.std(ddof=1) if len(a) > 1 else 0.0),
                "cpu_max": float(a.max()), "mem_max": float(max(mem)) if mem else 0.0,
                "threads": int(max(thr)) if thr else 0, "n": len(cpu)}

    def read_thread_cpu(self):
        f = self.rundir / "slam_thread_cpu.csv"
        if not f.exists():
            return {}
        by_thread: dict = {}
        with open(f, newline="") as fh:
            for row in csv.DictReader(fh):
                name = row.get("thread_name", "").strip()
                if not name:
                    continue
                try:
                    by_thread.setdefault(name, []).append(float(row["cpu_percent"]))
                except (KeyError, ValueError):
                    continue
        out = {}
        for name, vals in by_thread.items():
            a = np.array(vals)
            out[name] = {"mean": float(a.mean()), "std": float(a.std(ddof=1) if len(a) > 1 else 0.0)}
        return out

    def thread_role_order(self, names):
        """Order/subset thread names for the per-thread CPU plot. Default: active
        threads (mean >= 0.5% of a core) highest-first, to drop the many near-zero
        runtime/DDS threads that just clutter the chart. Override to pin a fixed
        role order (see orbslam2.py). `names` is {name: {mean,std}}."""
        active = [n for n in names if names[n]["mean"] >= 0.5]
        pool = active or list(names)   # never return empty → never draw a blank plot
        return sorted(pool, key=lambda n: names[n]["mean"], reverse=True)

    # ── plot helpers (paper style, matching generate_paper_images.py) ─────────
    def _save(self, fig, name):
        fig.tight_layout()
        fig.savefig(self.rundir / name, dpi=220, bbox_inches="tight")
        plt.close(fig)
        print(f"  wrote {name}")

    def _single_bar(self, value, std, ylabel, title, filename, ylim=None, lines=None):
        """One-column bar (mean ± std) — the single-HIL-run analogue of the
        study's per-sequence bars. `lines` = [(y, text, color)] reference lines."""
        fig, ax = plt.subplots(figsize=(4.5, 6))
        ax.bar([0], [value], width=0.5, yerr=[std] if std else None, capsize=6,
               color=self.color, edgecolor="black", linewidth=0.4, alpha=0.9)
        ax.set_xticks([0])
        ax.set_xticklabels([self.label])
        ax.set_ylabel(ylabel)
        ax.set_title(title)
        if ylim:
            ax.set_ylim(*ylim)
        if lines:
            for y, text, col in lines:
                ax.axhline(y, color=col, linestyle="--", linewidth=1.0)
                ax.text(0.45, y, text, color=col, ha="right", va="bottom", fontsize=9)
        ax.grid(axis="y", alpha=0.25)
        self._save(fig, filename)

    def plot_rmse(self, ate, mission_ate=None):
        # No error bar: a single HIL run has no across-run spread (the study's
        # RMSE error bars were std across N runs). The per-pose APE spread is
        # reported separately as ATE_std_m in the metrics CSV.
        # Primary bar is the mission-only ATE (excludes the init_gate's
        # pre-mission warm-up window) when available -- that's the number that
        # reflects actual tracking quality during the flight, not the whole-bag
        # one, which a brief high-error settling period right after init can
        # disproportionately inflate (RMSE squares errors).
        headline = mission_ate if mission_ate is not None else ate
        note = "" if mission_ate is not None else " (whole bag — no FSM marker found)"
        top = max(0.16, headline["rmse"] * 1.3)
        self._single_bar(headline["rmse"], 0.0, "APE RMSE (m)",
                         f"{self.label} — mission APE RMSE (HIL run){note}", "fig_slam_rmse.png",
                         ylim=(0, top), lines=[(y, t, "grey") for y, t in _RMSE_LINES])

    def plot_frontend_bar(self, durs):
        if len(durs) == 0:
            print("  (no front-end timing — fig_slam_frontend_bar.png skipped)")
            return
        mean, std = float(durs.mean()), float(durs.std(ddof=1) if len(durs) > 1 else 0.0)
        top = max(_FE_BUDGET_MS * 1.2, (mean + std) * 1.3)
        self._single_bar(mean, std, "Front-end full-tracking time (ms)",
                         f"{self.label} — front-end time ({len(durs)} frames, "
                         f"{1000.0/mean:.1f} Hz)", "fig_slam_frontend_bar.png",
                         ylim=(0, top), lines=[(_FE_BUDGET_MS, "20 Hz budget", "firebrick")])

    def plot_frontend_timeseries(self, x, durs):
        if len(durs) == 0:
            return
        fig, ax = plt.subplots(figsize=(9, 4))
        ax.plot(x, durs, color=self.color, lw=0.8, alpha=0.8)
        mean = float(durs.mean())
        ax.axhline(mean, color="k", ls="--", lw=1.0, label=f"mean {mean:.1f} ms")
        ax.axhline(_FE_BUDGET_MS, color="firebrick", ls="--", lw=1.0, label="20 Hz budget")
        ax.set_xlabel("frame (time order)"); ax.set_ylabel("front-end time (ms)")
        ax.set_title(f"{self.label} — front-end tracking latency per frame")
        ax.legend(fontsize=8); ax.grid(True, alpha=0.25)
        self._save(fig, "fig_slam_frontend_timing.png")

    def plot_cpu_total(self, cpu):
        if not cpu:
            return
        top = max(260.0, cpu["cpu_max"] * 1.15)
        self._single_bar(cpu["cpu_mean"], cpu["cpu_std"], "CPU usage (% of one core)",
                         f"{self.label} — total CPU (HIL run)", "fig_slam_cpu_total.png",
                         ylim=(0, top), lines=[(y, t, "grey") for y, t in _CPU_CORE_LINES])

    def plot_cpu_thread(self, threads):
        if not threads:
            print("  (no per-thread CPU — fig_slam_cpu_per_thread.png skipped)")
            return
        order = self.thread_role_order(threads)
        means = [threads[n]["mean"] for n in order]
        stds = [threads[n]["std"] for n in order]
        fig, ax = plt.subplots(figsize=(max(6, len(order) * 1.1 + 1), 5))
        x = np.arange(len(order))
        ax.bar(x, means, yerr=stds, capsize=4, color=_THREAD_COLOR,
               edgecolor="black", linewidth=0.4)
        ax.set_xticks(x); ax.set_xticklabels(order, rotation=25, ha="right")
        ax.set_ylabel("CPU usage (% of one core)")
        ax.set_title(f"{self.label} — per-thread CPU usage")
        ax.set_ylim(0, max(400.0, max(means) * 1.2 if means else 400.0))
        for y, _t in _CPU_CORE_LINES:
            ax.axhline(y, color="grey", linestyle="--", linewidth=1.0)
        ax.grid(axis="y", alpha=0.25)
        self._save(fig, "fig_slam_cpu_per_thread.png")

    def plot_trajectory(self, gt_full, ref, est_aligned, scale, ate):
        """GT dashed grey + aligned SLAM solid, matching *_trajectory_xy.png."""
        gt_len = float(np.sum(np.linalg.norm(np.diff(gt_full[:, 1:3], axis=0), axis=1)))
        est_xy = est_aligned.positions_xyz[:, :2]
        fig, ax = plt.subplots(figsize=(7, 8))
        ax.plot(gt_full[:, 1], gt_full[:, 2], "--", color="gray", lw=1.5,
                label=f"GT ({gt_len:.1f} m)")
        ax.plot(est_xy[:, 0], est_xy[:, 1], "-", color=self.color, lw=2.0,
                label=f"{self.label} (s={scale:.3f})")
        ax.set_xlabel("x (m)"); ax.set_ylabel("y (m)")
        ax.set_title(f"{self.label} — trajectory  (whole-bag APE RMSE {ate['rmse']:.4f} m)")
        ax.axis("equal"); ax.legend(loc="best"); ax.grid(True, alpha=0.3)
        self._save(fig, "fig_slam_trajectory.png")

    # ── coverage sanity check (did SLAM actually track the mission?) ──────────
    def compute_coverage(self, slam, gt, bench, scale):
        """SLAM path length (scaled) vs GT path length after FSM start — catches
        a low RMSE that only looks good because SLAM barely moved. None if no FSM."""
        fsm_t = self._find_fsm_start(bench)
        if fsm_t is None:
            return None, None, None
        gt_fsm = gt[gt[:, 0] >= fsm_t][:, 1:4]
        slam_fsm = slam[slam[:, 0] >= fsm_t][:, 1:4]
        if len(gt_fsm) < 2 or len(slam_fsm) < 2:
            return None, None, None
        gt_len = float(np.sum(np.linalg.norm(np.diff(gt_fsm, axis=0), axis=1)))
        slam_len = float(np.sum(np.linalg.norm(np.diff(slam_fsm, axis=0), axis=1))) * scale
        if gt_len < 0.05:
            return gt_len, slam_len, None
        return gt_len, slam_len, slam_len / gt_len * 100.0

    # ── orchestration ─────────────────────────────────────────────────────────
    def run(self):
        slam, gt, bench = self.read_bag()
        if len(slam) == 0:
            sys.exit("no /slam/pose in bag — SLAM never published poses (tracking failure?)")
        if len(gt) == 0:
            sys.exit("no /sim/drone_pose in bag — GT not recorded")

        # TUM files first -- compute_ate()/compute_ate_mission() shell out to
        # the real evo_ape CLI, which reads these from disk (not in-memory arrays).
        self._write_tum(self.rundir / "gt_traj.tum", gt[:, 0], gt[:, 1:4])
        self._write_tum(self.rundir / "slam_traj.tum", slam[:, 0], slam[:, 1:4])
        ate, ref, est_aligned, scale = self.compute_ate(slam, gt)
        if ate is None:
            sys.exit("evo_ape failed on the whole-bag trajectory — see stderr above")
        mission_ate_result = self.compute_ate_mission(slam, gt, bench)
        mission_ate = mission_ate_result[0] if mission_ate_result is not None else None

        fe_x, durs = self.read_frontend_timing()
        cpu = self.read_cpu()
        threads = self.read_thread_cpu()
        gt_cov, slam_cov, cov_pct = self.compute_coverage(slam, gt, bench, scale)

        # ── assemble metrics ─────────────────────────────────────────────────
        # "_full_" = whole bag (includes the init_gate's pre-mission warm-up
        # window). "_mission_" = restricted to t >= FSM start -- the number
        # that actually reflects tracking quality during the flight; the
        # warm-up window is brief but its error is disproportionately larger
        # (SLAM has only just initialized), and RMSE squares errors, so it can
        # noticeably inflate the whole-bag figure. Report mission_, not full_,
        # unless comparing against something that only has whole-bag numbers.
        m = self.metrics
        m["slam_type"] = self.slam_type
        m["label"] = self.label
        m["ATE_RMSE_full_m"] = round(ate["rmse"], 6)
        m["ATE_mean_full_m"] = round(ate["mean"], 6)
        m["ATE_median_full_m"] = round(ate["median"], 6)
        m["ATE_std_full_m"] = round(ate["std"], 6)
        m["ATE_min_full_m"] = round(ate["min"], 6)
        m["ATE_max_full_m"] = round(ate["max"], 6)
        if mission_ate is not None:
            m["ATE_RMSE_mission_m"] = round(mission_ate["rmse"], 6)
            m["ATE_mean_mission_m"] = round(mission_ate["mean"], 6)
            m["ATE_median_mission_m"] = round(mission_ate["median"], 6)
            m["ATE_std_mission_m"] = round(mission_ate["std"], 6)
            m["ATE_min_mission_m"] = round(mission_ate["min"], 6)
            m["ATE_max_mission_m"] = round(mission_ate["max"], 6)
        m["umeyama_scale"] = round(scale, 6)
        m["n_slam_poses"] = int(len(slam))
        m["n_associated"] = int(ref.num_poses)
        if durs.size:
            m["FE_full_tracking_ms_mean"] = round(float(durs.mean()), 3)
            m["FE_full_tracking_ms_std"] = round(float(durs.std(ddof=1) if len(durs) > 1 else 0.0), 3)
            m["FE_hz"] = round(1000.0 / float(durs.mean()), 2) if durs.mean() > 0 else 0.0
            m["FE_n_frames"] = int(len(durs))
        if cpu:
            m["CPU_percent_mean"] = round(cpu["cpu_mean"], 2)
            m["CPU_percent_max"] = round(cpu["cpu_max"], 2)
            m["MEM_mb_max"] = round(cpu["mem_max"], 1)
            m["threads"] = cpu["threads"]
        if cov_pct is not None:
            m["fsm_gt_path_length_m"] = round(gt_cov, 3)
            m["fsm_slam_path_length_m"] = round(slam_cov, 3)
            m["slam_coverage_after_fsm_pct"] = round(cov_pct, 2)

        self._write_metrics_csv()

        # ── plots ────────────────────────────────────────────────────────────
        self.plot_trajectory(gt, ref, est_aligned, scale, ate)
        self.plot_rmse(ate, mission_ate)
        self.plot_frontend_bar(durs)
        self.plot_frontend_timeseries(fe_x, durs)
        self.plot_cpu_total(cpu)
        self.plot_cpu_thread(threads)

        print(f"\n=== SLAM eval — {self.label} — {self.rundir.name} ===")
        for k, v in m.items():
            print(f"  {k:28s}  {v}")

    def _write_metrics_csv(self):
        with open(self.rundir / "slam_metrics.csv", "w", newline="") as f:
            w = csv.writer(f)
            w.writerow(["metric", "value"])
            for k, v in self.metrics.items():
                w.writerow([k, v])
